function calcIns(i){
    var L=REG.locations[i.loc],P=REG.programs[i.prog],S=REG.shapes[i.shape],F=REG.fuels[i.fuel],lf=REG.profiles[i.profile].lf;
    var h=Math.sqrt(i.sqft/S.r),per=2*h*(S.r+1),wall=per*i.fh*i.floors*i.exp,net=i.area>0?i.area:wall*(1-i.win);
    var dU=1/i.rOld-1/i.rNew,hdd=i.hdd>0?i.hdd:L.hdd,cdd=i.cdd>0?i.cdd:L.cdd;
    var heatBtu=dU*net*hdd*24*lf*.9,coolBtu=i.cool?dU*net*cdd*24*lf*.75:0;
    var heatIn=heatBtu/i.eff,heatUnits=heatIn/F.btu,heatCost=heatUnits*i.prices[F.price];
    var coolKwh=coolBtu/3412/i.cop,coolCost=coolKwh*i.prices.elec;
    var elec=(i.fuel==="electric"?heatUnits:0)+coolKwh,annual=heatCost+coolCost,rate=i.fuel==="electric"?P.rate.electric:P.rate.other;
    return {
        per:per,net:net,dR:i.rOld>0?i.rNew-i.rOld:0,heatUnits:heatUnits,unit:F.u,coolKwh:coolKwh,elec:elec,site:(heatIn+coolKwh*3412)/1e6,annual:annual,rate:rate,inc:net*rate,val10:annual*10
    };
}
